  }),\n        ]}\n        navigateToApp={navigateToApp}\n        onNavItemClick={onNavItemClick}\n      />\n    );\n    expect(container).toMatchSnapshot();\n    expect(container.querySelectorAll('.nav-link-item-btn').length).toEqual(5);\n    fireEvent.click(getByTestId('collapsibleNavAppLink-pure'));\n    expect(navigateToApp).toBeCalledWith('pure');\n  });\n});\n\ndescribe('<CollapsibleNavGroupEnabled />', () => {\n  function mockProps(\n    props?: Partial<CollapsibleNavGroupEnabledProps> & {\n      navGroupsMap?: Record<string, NavGroupItemInMap>;\n    }\n  ): CollapsibleNavGroupEnabledProps {\n    const currentNavGroup$ = new BehaviorSubject<NavGroupItemInMap | undefined>(undefined);\n    const navGroupsMap$ = new BehaviorSubject<Record<string, NavGroupItemInMap>>({\n      [ALL_USE_CASE_ID]: {\n        ...DEFAULT_NAV_GROUPS[ALL_USE_CASE_ID],\n        navLinks: [\n          {\n            id: 'link-in-all',\n            title: 'link-in-all',\n          },\n        ],\n      },\n      [DEFAULT_NAV_GROUPS.observability.id]: {\n        ...DEFAULT_NAV_GROUPS.observability,\n        navLinks: [\n          {\n            id: 'link-in-observability',\n            title: 'link-in-observability',\n            showInAllNavGroup: true,\n          },\n        ],\n      },\n      ...props?.navGroupsMap,\n    });\n    return {\n      appId$: new BehaviorSubject('test'),\n      basePath: mockBasePath,\n      id: 'collapsibe-nav',\n      isLocked: false,\n      isNavOpen: false,\n      navLinks$: new BehaviorSubject([\n        {\n          id: 'link-in-all',\n          title: 'link-in-all',\n          baseUrl: '',\n          href: '',\n        },\n        {\n          id: 'link-in-observability',\n          title: 'link-in-observability',\n          baseUrl: '',\n          href: '',\n        },\n        {\n          id: 'link-in-analytics',\n          title: 'link-in-analytics',\n          baseUrl: '',\n          href: '',\n        },\n      ]),\n      storage: new StubBrowserStorage(),\n      onIsLockedUpdate: () => {},\n      closeNav: () => {},\n      navigateToApp: () => Promise.resolve(),\n      navigateToUrl: () => Promise.resolve(),\n      customNavLink$: new BehaviorSubject(undefined),\n      logos: getLogos({}, mockBasePath.serverBasePath),\n      navGroupsMap$,\n      navControlsLeftBottom$: new BehaviorSubject([]),\n      currentNavGroup$,\n      setCurrentNavGroup: (val: string | undefined) => {\n        if (val) {\n          const currentNavGroup = navGroupsMap$.getValue()[val];\n          if (currentNavGroup) {\n            currentNavGroup$.next(currentNavGroup);\n          }\n        } else {\n          currentNavGroup$.next(undefined);\n        }\n      },\n      ...props,\n    };\n  }\n  it('should render correctly', () => {\n    const props = mockProps({\n      isNavOpen: true,\n      navGroupsMap: {\n        [DEFAULT_NAV_GROUPS.analytics.id]: {\n          ...DEFAULT_NAV_GROUPS.analytics,\n          navLinks: [\n            {\n              id: 'link-in-analytics',\n              title: 'link-in-analytics',\n              showInAllNavGroup: true,\n            },\n          ],\n        },\n      },\n    });\n    const { container } = render(<CollapsibleNavGroupEnabled {...props} />);\n    expect(container).toMatchSnapshot();\n    const { container: isNavOpenCloseContainer } = render(\n      <CollapsibleNavGroupEnabled {...props} isNavOpen={false} />\n    );\n    expect(isNavOpenCloseContainer).toMatchSnapshot();\n  });\n\n  it('should render correctly when only one visible use case is provided', () => {\n    const props = mockProps();\n    const { getAllByTestId } = render(<CollapsibleNavGroupEnabled {...props} isNavOpen />);\n    expect(getAllByTestId('collapsibleNavAppLink-link-in-observability').length).toEqual(1);\n  });\n\n  it('should show all use case by default and able to click see all', async () => {\n    const props = mockProps({\n      navGroupsMap: {\n        [DEFAULT_NAV_GROUPS.analytics.id]: {\n          ...DEFAULT_NAV_GROUPS.analytics,\n          navLinks: [\n            {\n              id: 'link-in-analytics',\n              title: 'link-in-analytics',\n              showInAllNavGroup: true,\n            },\n          ],\n        },\n      },\n    });\n    const { container, getAllByTestId, getByTestId } = render(\n      <CollapsibleNavGroupEnabled {...props} isNavOpen />\n    );\n    fireEvent.click(getAllByTestId('collapsibleNavAppLink-link-in-analytics')[1]);\n    expect(getAllByTestId('collapsibleNavAppLink-link-in-analytics').length).toEqual(1);\n    expect(container).toMatchSnapshot();\n    fireEvent.click(getByTestId('back'));\n    expect(getAllByTestId('collapsibleNavAppLink-link-in-analytics').length).toEqual(2);\n  });\n});\n"],"mappings":";;AAqBAA,WAAA,GAAKC,IAAI,CAAC,qCAAqC,EAAE,OAAO;EACtDC,iBAAiB,EAAGC,KAA6B,iBAC/CC,MAAA,CAAAC,OAAA,CAAAC,aAAA;IAAQ,kBAAe,MAAM;IAACC,OAAO,EAAEJ,KAAK,CAACK;EAAY,GAAC,SAElD;AAEZ,CAAC,CAAC,CAAC;AAtBH,IAAAJ,MAAA,GAAAK,sBAAA,CAAAC,OAAA;AACA,IAAAC,KAAA,GAAAD,OAAA;AACA,IAAAE,OAAA,GAAAF,OAAA;AACA,IAAAG,qBAAA,GAAAH,OAAA;AACA,IAAAI,8BAAA,GAAAJ,OAAA;AAOA,IAAAK,MAAA,GAAAL,OAAA;AACA,IAAAM,OAAA,GAAAN,OAAA;AACA,IAAAO,OAAA,GAAAP,OAAA;AAAyE,SAAAD,uBAAAS,GAAA,WAAAA,GAAA,IAAAA,GAAA,CAAAC,UAAA,GAAAD,GAAA,KAAAb,OAAA,EAAAa,GAAA;AAAA,SAAAE,SAAA,IAAAA,QAAA,GAAAC,MAAA,CAAAC,MAAA,GAAAD,MAAA,CAAAC,MAAA,CAAAC,IAAA,eAAAC,MAAA,aAAAC,CAAA,MAAAA,CAAA,GAAAC,SAAA,CAAAC,MAAA,EAAAF,CAAA,UAAAG,MAAA,GAAAF,SAAA,CAAAD,CAAA,YAAAI,GAAA,IAAAD,MAAA,QAAAP,MAAA,CAAAS,SAAA,CAAAC,cAAA,CAAAC,IAAA,CAAAJ,MAAA,EAAAC,GAAA,KAAAL,MAAA,CAAAK,GAAA,IAAAD,MAAA,CAAAC,GAAA,gBAAAL,MAAA,YAAAJ,QAAA,CAAAa,KAAA,OAAAP,SAAA;AAAA,SAAA1B,YAAA;EAAA;IAAAkC;EAAA,IAAAxB,OAAA;EAAAV,WAAA,GAAAA,CAAA,KAAAkC,IAAA;EAAA,OAAAA,IAAA;AAAA;AAlBzE;AACA;AACA;AACA;AA0BA,MAAMC,YAAY,GAAGC,sBAAe,CAACC,mBAAmB,CAAC;EAAEC,QAAQ,EAAE;AAAQ,CAAC,CAAC,CAACA,QAAQ;AAExFC,QAAQ,CAAC,eAAe,EAAE,MAAM;EAC9B,MAAMC,gBAAgB,GACpBC,OAA2D,KACZ;IAC/CC,OAAO,EAAE,EAAE;IACXC,IAAI,EAAE,EAAE;IACRC,EAAE,EAAE,EAAE;IACNC,KAAK,EAAE,EAAE;IACT,